(function () {
  'use strict';

  function deepFreeze(target) {
    if (target && typeof target === 'object' && !Object.isFrozen(target)) {
      Object.freeze(target);
      Object.keys(target).forEach(function (key) {
        deepFreeze(target[key]);
      });
    }
    return target;
  }

  window.MARALUXE_ASSETS = deepFreeze({
    logo: "data:image/webp;base64,",
    banners: {
      hero: "data:image/webp;base64,",
      cocktails: "data:image/webp;base64,",
      spirits: "data:image/webp;base64,",
      green: "data:image/webp;base64,",
      lounge: "data:image/webp;base64,",
      wine: "data:image/webp;base64,"
    },
    cocktails: {
      coconutVelvetThumb: "data:image/webp;base64,",
      coconutVelvetFull: "data:image/webp;base64,",
      mangoSplashThumb: "data:image/webp;base64,",
      oasisThumb: "data:image/webp;base64,",
      strawberryBlissThumb: "data:image/webp;base64,",
      tropicalSunsetThumb: "data:image/webp;base64,"
    }
  });
})();
